import heapq

def match(orders):
    trades = []
    buy_book = []  # max-heap: (-price, seq, id)
    sell_book = []  # min-heap: (price, seq, id)
    orders_info = {}  # id -> [side, price, remaining_qty, active]
    seq_counter = 0

    def add_resting(side, oid, price, qty, seq):
        if side == 'buy':
            heapq.heappush(buy_book, (-price, seq, oid))
        else:
            heapq.heappush(sell_book, (price, seq, oid))

    def clean_buy_top():
        while buy_book:
            negprice, seq, oid = buy_book[0]
            info = orders_info.get(oid)
            if info is None or not info[3] or info[2] <= 0:
                heapq.heappop(buy_book)
            else:
                return True
        return False

    def clean_sell_top():
        while sell_book:
            price, seq, oid = sell_book[0]
            info = orders_info.get(oid)
            if info is None or not info[3] or info[2] <= 0:
                heapq.heappop(sell_book)
            else:
                return True
        return False

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info[3] and info[2] > 0:
                info[3] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty
        orders_info[oid] = [side, price, remaining, True]

        if side == 'buy':
            while remaining > 0 and clean_sell_top():
                s_price, s_seq, s_oid = sell_book[0]
                if typ != 'market' and price is not None and s_price > price:
                    break
                s_info = orders_info[s_oid]
                trade_qty = min(remaining, s_info[2])
                trades.append([oid, s_oid, s_price, trade_qty])
                remaining -= trade_qty
                s_info[2] -= trade_qty
                orders_info[oid][2] = remaining
                if s_info[2] <= 0:
                    heapq.heappop(sell_book)
            orders_info[oid][2] = remaining
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                add_resting('buy', oid, price, remaining, seq_counter)
            else:
                orders_info[oid][3] = False if remaining <= 0 else orders_info[oid][3]
                if typ != 'limit':
                    orders_info[oid][3] = False
        else:  # sell
            while remaining > 0 and clean_buy_top():
                negprice, b_seq, b_oid = buy_book[0]
                b_price = -negprice
                if typ != 'market' and price is not None and b_price < price:
                    break
                b_info = orders_info[b_oid]
                trade_qty = min(remaining, b_info[2])
                trades.append([b_oid, oid, b_price, trade_qty])
                remaining -= trade_qty
                b_info[2] -= trade_qty
                orders_info[oid][2] = remaining
                if b_info[2] <= 0:
                    heapq.heappop(buy_book)
            orders_info[oid][2] = remaining
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                add_resting('sell', oid, price, remaining, seq_counter)
            else:
                if typ != 'limit':
                    orders_info[oid][3] = False

    return trades

